import React, { useState } from 'react';
import './Login.css';

function Login({ allerVers }) {
  const [telephone, setTelephone] = useState('');
  const [motDePasse, setMotDePasse] = useState('');
  const [message, setMessage] = useState('');
  const [chargement, setChargement] = useState(false);

  const handleConnexion = async () => {
    setChargement(true);
    setMessage('');

    try {
      const reponse = await fetch('http://localhost:5000/api/auth/connexion', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          telephone,
          mot_de_passe: motDePasse
        })
      });

      const donnees = await reponse.json();

      if (reponse.ok) {
        localStorage.setItem('token', donnees.token);
        localStorage.setItem('utilisateur', JSON.stringify(donnees.utilisateur));
        setMessage('✅ ' + donnees.message);
        setTimeout(() => allerVers('accueil'), 2000);
      } else {
        setMessage('❌ ' + donnees.message);
      }

    } catch (erreur) {
      setMessage('❌ Impossible de contacter le serveur');
    }

    setChargement(false);
  };

  return (
    <div className="login-page">
      <div className="login-box">
        <h1 className="login-logo">🎵 Varim Music</h1>
        <h2 className="login-titre">Connexion</h2>
        <p className="login-sous-titre">Entrez votre numéro de téléphone</p>

        {message && (
          <div className="login-message">{message}</div>
        )}

        <div className="login-champ">
          <label>Numéro de téléphone</label>
          <input
            type="tel"
            placeholder="Ex: 06 123 45 67"
            value={telephone}
            onChange={(e) => setTelephone(e.target.value)}
          />
        </div>

        <div className="login-champ">
          <label>Mot de passe</label>
          <input
            type="password"
            placeholder="Votre mot de passe"
            value={motDePasse}
            onChange={(e) => setMotDePasse(e.target.value)}
          />
        </div>

        <button
          className="login-btn"
          onClick={handleConnexion}
          disabled={chargement}
        >
          {chargement ? 'Connexion en cours...' : 'Se connecter'}
        </button>

        <p className="login-lien">
          Pas encore de compte ? <a href="#" onClick={() => allerVers('register')}>S'inscrire</a>
        </p>
      </div>
    </div>
  );
}

export default Login;
